require_once __DIR__.'/../app/bootstrap.php';$provider=$_GET['provider']??'drive';if(!in_array($provider,['drive','youtube'],true))exit('Invalid provider.');$security->startSession();if(empty($_GET['code'])){redirect($oauth->authorizationUrl($provider));}try{$tokens=$oauth->callback($provider,(string)$_GET['code'],(string)($_GET['state']??''));if($provider==='drive'){$info=$oauth->userInfo($tokens['access_token']);$db->exec("UPDATE google_drive_connections SET status='disabled',updated_at=? WHERE status='connected'",[now_sql()]);$db->insert('INSERT INTO google_drive_connections(account_email,token_ciphertext,token_expires_at,status,created_at,updated_at) VALUES(?,?,?,?,?,?)',[$info['email']??null,$security->encrypt(json_encode_safe($tokens)),date('Y-m-d H:i:s',$tokens['expires_at']),'connected',now_sql(),now_sql()]);redirect(base_url('index.php?page=folders&connected=drive'));}$yt=new YouTube($tokens['access_token']);$result=$yt->channel();$item=$result['items'][0]??null;if(!$item)throw new RuntimeException('Authorized Google account does not expose a YouTube channel.');$channelId=$item['id'];$name=$item['snippet']['title']??'YouTube Channel';$existing=$db->one('SELECT id FROM youtube_channels WHERE channel_id=?',[$channelId]);$cipher=$security->encrypt(json_encode_safe($tokens));if($existing){$old=$db->one('SELECT token_ciphertext FROM youtube_channels WHERE id=?',[$existing['id']]);$new=$tokens;if(empty($new['refresh_token'])&&$old){$oldBundle=json_decode($security->decrypt($old['token_ciphertext']),true);$new['refresh_token']=$oldBundle['refresh_token']??null;}$db->exec("UPDATE youtube_channels SET channel_name=?,token_ciphertext=?,token_expires_at=?,status='connected',last_error=NULL,updated_at=? WHERE id=?",[$name,$security->encrypt(json_encode_safe($new)),date('Y-m-d H:i:s',$new['expires_at']),now_sql(),$existing['id']]);}else{$db->insert('INSERT INTO youtube_channels(channel_id,channel_name,token_ciphertext,token_expires_at,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',[$channelId,$name,$cipher,date('Y-m-d H:i:s',$tokens['expires_at']),'connected',now_sql(),now_sql()]);}redirect(base_url('index.php?page=channels&connected=youtube'));}catch(Throwable $e){$services->log('ERROR','oauth.callback_failed',$e->getMessage(),['provider'=>$provider]);http_response_code(500);echo '<h2>OAuth failed</h2><p>'.e($e->getMessage()).'</p><p><a href="'.e(base_url('index.php')).'">Back to dashboard</a></p>';}
